18	const getMemoSortTime = (memo: Memo, timeBasis: MemoTimeBasis): Date | undefined => {
19	  const timestamp = timeBasis === "update_time" ? memo.updateTime : memo.createTime;
20	  return timestamp ? timestampDate(timestamp) : undefined;
21	};
